<?php
declare(strict_types=1); namespace App\Http\Controller;
use App\Application; use App\Http; use RuntimeException; use Throwable;
final class VehiclesController { private $app; public function __construct(Application $app){$this->app=$app;} public function handle(): void {$pdo=$this->app->pdo();$me=$this->app->auth()->requireVehicleManager();try{if($_SERVER['REQUEST_METHOD']==='POST'){$this->app->session()->verifyCsrf();$action=(string)($_POST['action']??'');if($action==='create'||$action==='update'){$id=(int)($_POST['id']??0);$name=trim((string)$_POST['name']);$vin=strtoupper(trim((string)$_POST['vin']));$battery=(float)str_replace(',','.',(string)$_POST['battery_kwh']);$nominal=(float)str_replace(',','.',(string)($_POST['battery_nominal_kwh']??$battery));$sohRaw=trim((string)($_POST['soh_manual_pct']??''));$soh=$sohRaw===''?null:(float)str_replace(',','.',$sohRaw);$home=trim((string)($_POST['home_label']??''));if($name===''||$vin===''||$battery<=0||$nominal<=0)throw new RuntimeException('Vyplňte název, VIN a kapacitu baterie.');if($soh!==null&&($soh<50||$soh>110))throw new RuntimeException('SoH zadejte v rozsahu 50–110 %.');if($action==='create'){$pdo->prepare('INSERT INTO vehicles(name,vin,battery_kwh,battery_nominal_kwh,soh_manual_pct,soh_manual_at,home_label) VALUES(?,?,?,?,?,IF(? IS NULL,NULL,NOW()),?)')->execute([$name,$vin,$battery,$nominal,$soh,$soh,$home?:null]);$this->app->session()->flash('Vozidlo bylo přidáno.');}else{$pdo->prepare('UPDATE vehicles SET name=?,vin=?,battery_kwh=?,battery_nominal_kwh=?,soh_manual_pct=?,soh_manual_at=IF(? IS NULL,NULL,NOW()),home_label=? WHERE id=?')->execute([$name,$vin,$battery,$nominal,$soh,$soh,$home?:null,$id]);$this->app->session()->flash('Vozidlo bylo upraveno.');}}elseif($action==='assign'){$vehicleId=(int)$_POST['vehicle_id'];$userIds=array_map('intval',$_POST['user_ids']??[]);$pdo->beginTransaction();$pdo->prepare('DELETE FROM user_vehicles WHERE vehicle_id=?')->execute([$vehicleId]);$ins=$pdo->prepare('INSERT INTO user_vehicles(user_id,vehicle_id) VALUES(?,?)');foreach(array_unique($userIds) as $uid)if($uid>0)$ins->execute([$uid,$vehicleId]);$pdo->prepare("UPDATE users u SET u.default_vehicle_id=NULL WHERE u.default_vehicle_id=? AND u.role='user' AND NOT EXISTS (SELECT 1 FROM user_vehicles uv WHERE uv.user_id=u.id AND uv.vehicle_id=?)")->execute([$vehicleId,$vehicleId]);$pdo->commit();$this->app->session()->flash('Přiřazení vozidla bylo uloženo.');}elseif($action==='delete'){if(!$this->app->auth()->isAdmin($me))throw new RuntimeException('Vozidlo může smazat pouze administrátor.');$pdo->prepare('DELETE FROM vehicles WHERE id=?')->execute([(int)$_POST['id']]);$this->app->session()->flash('Vozidlo a jeho jízdy byly smazány.');}Http::redirect('vehicles.php');}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$this->app->session()->flash($e->getMessage(),'error');Http::redirect('vehicles.php');}$vehicles=$pdo->query('SELECT v.*, (SELECT COUNT(*) FROM trips t WHERE t.vehicle_id=v.id) trip_count FROM vehicles v ORDER BY v.name')->fetchAll();$users=$pdo->query("SELECT id,name,email FROM users WHERE active=1 ORDER BY name")->fetchAll();$assigned=[];foreach($pdo->query('SELECT user_id,vehicle_id FROM user_vehicles') as $r)$assigned[(int)$r['vehicle_id']][]=(int)$r['user_id'];$flash=$this->app->session()->pullFlash();$this->app->template()->render('vehicles',['app'=>$this->app,'me'=>$me,'vehicles'=>$vehicles,'users'=>$users,'assigned'=>$assigned,'flash'=>$flash]);}}
